package com.smartresponse.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="emergency_updates") public class EmergencyUpdate {@Id @GeneratedValue private UUID id;@ManyToOne(optional=false) @JoinColumn(name="emergency_id") private Emergency emergency;@ManyToOne @JoinColumn(name="author_id") private AppUser author;private String updateType;private String message;private boolean visibleToReporter=true;private Instant createdAt=Instant.now();protected EmergencyUpdate(){}public EmergencyUpdate(Emergency e,AppUser a,String t,String m){emergency=e;author=a;updateType=t;message=m;}public String getMessage(){return message;}public String getUpdateType(){return updateType;}public Instant getCreatedAt(){return createdAt;}}
